actions.script:
const out = ec.service.sync().name('org.moqui.impl.FileServices.list#PublicShare').parameters({token: token || '', grant: grant || null,
    path: path || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {fileList: out.fileList || [], uploadOnly: out.uploadOnly === true})

const out = ec.service.sync().name('org.moqui.impl.FileServices.download#PublicShare').parameters({token: token || '', grant: grant || null,
    path: path || null}).call()
if (ec.message.hasError() || !out.location) { ec.web.sendJsonResponse({}); return }
// the visitor has no user: the file the service answered after its token and grant checks is read with authorization
// off (the drive's database files are entity rows). The download is named by its location's last segment, so a zip
// made under a random name gets the folder's name.
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    let location = out.location
    const last = String(location).split('/').pop()
    if (out.fileName && last !== out.fileName) {
        const target = `runtime://tmp/drive-download/${ec.user.randomString(16)}/${String(out.fileName).replace(/[\\/*?"<>|#%]/g, '_').replace(/:/g, '_')}`
        const stream = ec.resource.getLocationReference(location).openStream()
        try { ec.resource.getLocationReference(target).putStream(stream) } finally { if (stream && stream.close) stream.close() }
        location = target
    }
    const inlineOk = /^(image\/(png|jpeg|gif|webp|bmp)|application\/pdf)$/.test(String(out.contentType || ''))
    ec.web.sendResourceResponse(location, String(inline) === 'true' && inlineOk)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
